from fastapi import FastAPI, HTTPException

app = FastAPI()

PLATFORMS: dict[int, int] = {}
PLATFORMS[{{train_a}}] = {{platform_a}}
PLATFORMS[{{train_b}}] = {{platform_b}}


def platform_for(train_id: int) -> dict[str, int]:
    if train_id not in PLATFORMS:
        raise HTTPException(status_code=404, detail="No such train")
    return {"train": train_id, "platform": PLATFORMS[train_id]}


